/** Case-insensitive excluded keyword matching (mirrors Python keyword_filter). */

const TITLE_ONLY_KEYWORDS = new Set([
  "ii",
  "iii",
  "iv",
  "grad",
  "graduate",
  "graduation",
  "undergrad",
]);

function escapeRegex(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function compileKeywordPattern(keyword: string): RegExp {
  const trimmed = keyword.trim();
  const lower = trimmed.toLowerCase();
  const escaped = escapeRegex(trimmed);
  if (TITLE_ONLY_KEYWORDS.has(lower)) {
    return new RegExp(`\\b${escaped}\\b`, "i");
  }
  if (lower.length <= 4 && /^[a-z]+$/i.test(lower)) {
    return new RegExp(`\\b${escaped}(?:uate|uation|s)?\\b`, "i");
  }
  return new RegExp(`\\b${escaped}\\b`, "i");
}

function keywordHaystack(
  job: { title: string; company?: string; description?: string | null },
  keyword: string,
): string {
  const key = keyword.trim().toLowerCase();
  if (TITLE_ONLY_KEYWORDS.has(key)) {
    return [job.title, job.company ?? ""].filter(Boolean).join("\n");
  }
  return [job.title, job.company ?? "", job.description ?? ""].filter(Boolean).join("\n");
}

export function matchesExcludedKeywords(
  job: { title: string; company?: string; description?: string | null },
  keywords: string[],
): string | null {
  const seen = new Set<string>();

  for (const raw of keywords) {
    const keyword = raw.trim();
    if (!keyword) continue;
    const key = keyword.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    const haystack = keywordHaystack(job, keyword);
    if (!haystack.trim()) continue;
    if (compileKeywordPattern(keyword).test(haystack)) {
      return keyword;
    }
  }
  return null;
}

export function isKeywordExcluded(
  job: { title: string; company?: string; description?: string | null },
  keywords: string[],
): boolean {
  return matchesExcludedKeywords(job, keywords) !== null;
}
